SELECT *, PERCENT_RANK() OVER (PARTITION BY carrier ORDER BY cost DESC NULLS FIRST) AS cost_percent_rank, RANK() OVER (PARTITION BY carrier ORDER BY cost DESC NULLS LAST) AS cost_rank, LAST_VALUE(cost, TRUE) OVER (PARTITION BY carrier ORDER BY shipped_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost, NTILE(3) OVER (PARTITION BY order_id ORDER BY cost DESC, id ASC) AS cost_bucket, LAST_VALUE(carrier, TRUE) OVER (PARTITION BY status, order_id ORDER BY shipped_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier FROM shipments
